import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Results and history","description":"","frontmatter":{},"headers":[],"relativePath":"guide/results.md","filePath":"guide/results.md","lastUpdated":1793111003000}'),o={name:"guide/results.md"};function s(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="results-and-history" tabindex="-1">Results and history <a class="header-anchor" href="#results-and-history" aria-label="Permalink to &quot;Results and history&quot;">​</a></h1><p>Inspect your reading list, select what matters, and export it into your own research workflow.</p><h2 id="three-independent-histories" tabindex="-1">Three independent histories <a class="header-anchor" href="#three-independent-histories" aria-label="Permalink to &quot;Three independent histories&quot;">​</a></h2><p>Search runs, analyses, and reviews are saved separately — each module in the sidebar shows its own history. Where history lives, how records are renamed, exported, or deleted, and what survives a reload: <a href="./workspace">Workspace and history</a>.</p><h2 id="read-a-paper-card" tabindex="-1">Read a paper card <a class="header-anchor" href="#read-a-paper-card" aria-label="Permalink to &quot;Read a paper card&quot;">​</a></h2><p>Results can include titles, authors, years, venues, abstracts, source links, identifiers, citation information, and relevance explanations. Availability depends on the source.</p><p>Relevance measures the match to <strong>your question</strong>. It is not a study-quality score or permission to cite a paper without reading it.</p><h2 id="journal-rankings-and-conference-acceptance" tabindex="-1">Journal rankings and conference acceptance <a class="header-anchor" href="#journal-rankings-and-conference-acceptance" aria-label="Permalink to &quot;Journal rankings and conference acceptance&quot;">​</a></h2><p>Cards can carry two kinds of venue labels. Open <strong>Details</strong> for the full entry.</p><ul><li><strong>Journal and venue rankings</strong>: CAS tier and Top (中科院分区), JCR quartile and Impact Factor, and the CCF class (A, B or C) of recommended conferences and journals, from <a href="https://github.com/hitfyd/ShowJCR" target="_blank" rel="noreferrer">ShowJCR</a>. CAS and JCR are matched by ISSN, otherwise by the exact journal title; Details says when the title was used. CCF is matched by the venue&#39;s full name or its abbreviation, such as NeurIPS; workshops get no CCF class. Only the JCR figure is an Impact Factor; CAS tiers, JCR quartiles and CCF classes are rankings.</li><li><strong>Chinese core journals</strong>: PKU Core (北大核心) and three separate CSSCI lists: CSSCI source journals, CSSCI source collections (集刊) and CSSCI Extended (扩展版), each with its edition. Details also show the edition. PaperSeek keeps this list. It has no ISSN, so it is matched by the Chinese journal title or a former title; brackets, full-width punctuation and a &quot;(中英文)&quot; marker do not count. A name shared by several journals, such as 北京大学学报 without its edition, gets no label.</li><li><strong>Open impact</strong>: a journal&#39;s 2-year mean citedness and h-index from OpenAlex. It needs no import and is not an Impact Factor.</li><li><strong>Conference acceptance</strong>: venue, year and Oral, Spotlight or Poster, from the PaperHub collection and OpenReview. Only papers a main conference track, NeurIPS Datasets &amp; Benchmarks or TMLR accepted count; workshop, rejected, withdrawn and under-review submissions do not.</li></ul><p>Labels are added when a search finishes. The ShowJCR tables download from GitHub on the first search and stay on this computer; <strong>Settings → Data sources → Journal rankings</strong> shows their editions and <strong>Update all</strong> fetches them again; the PKU Core and CSSCI list downloads with them. The network proxy applies to these downloads. Where GitHub is unreachable, download the same file from ShowJCR (<code>FQBJCR2025-UTF8.csv</code>, <code>JCR2025-UTF8.csv</code>, <code>CCF2026-UTF8.csv</code>) and use <strong>Import local file</strong>. The PKU Core and CSSCI list imports from <code>.xlsx</code> or CSV with the columns 刊名, 收录 and 曾用名. Run a search again to label it with a new edition.</p><h2 id="filter-sort-and-select" tabindex="-1">Filter, sort, and select <a class="header-anchor" href="#filter-sort-and-select" aria-label="Permalink to &quot;Filter, sort, and select&quot;">​</a></h2><p>Result controls search the returned set, apply available filters, and change the order. They do not issue a fresh external search.</p><p><strong>Journal</strong> keeps papers in a CAS tier, CAS Top, a JCR quartile range, a CCF class range (A, A–B, A–C), PKU Core, CSSCI source journals, CSSCI source collections, or CSSCI Extended. <strong>Accepted</strong> keeps papers with conference acceptance, Oral only, or Oral and Spotlight. <strong>By impact factor</strong> sorts by JCR Impact Factor, then by OpenAlex open impact. Papers without a label are left out by these filters, not guessed.</p><p>Select individual papers for a smaller export or a review, and check the selected count before continuing. <strong>Select loaded</strong> applies only to the currently loaded papers. Review creation requires 2–256 selected papers. Switching modules preserves the selection during this session.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Use</th></tr></thead><tbody><tr><td>CSV</td><td>Spreadsheets and manual screening</td></tr><tr><td>JSON</td><td>Structured downstream processing, including journal and acceptance labels</td></tr><tr><td>BibTeX</td><td>Zotero, JabRef, LaTeX</td></tr><tr><td>RIS</td><td>Zotero, EndNote, Mendeley</td></tr><tr><td>Selected (any format)</td><td>Only the selected papers</td></tr></tbody></table><p>The <strong>Export</strong> menu groups complete and selected downloads. BibTeX and RIS mark journal articles, conference papers and preprints with their own entry types, carry volume, issue, pages and ISSN when the source provides them, and put conference acceptance (for example &quot;ICLR 2025 Oral&quot;) in the note field. Journal rankings stay out of these files. A complete export covers the stored results, not just the visible page. Original-record links take you to the source; PaperSeek does not bulk-download paywalled text.</p><p><a href="./reviews">Review exports</a> use Markdown, Word, and BibTeX.</p><h2 id="reopen-history" tabindex="-1">Reopen history <a class="header-anchor" href="#reopen-history" aria-label="Permalink to &quot;Reopen history&quot;">​</a></h2><p>Community history belongs to the local database. Online history belongs to your account. <a href="./../online/privacy#search-without-signing-in">Signing in after an anonymous search</a> does not backfill it.</p><p>A saved run retains its actual settings. Reopening it does not replace its model or budget with current defaults; older unrecorded fields remain unknown.</p><p>You can delete finished history items after exporting anything you need. Active tasks must end first.</p><h2 id="start-a-review" tabindex="-1">Start a review <a class="header-anchor" href="#start-a-review" aria-label="Permalink to &quot;Start a review&quot;">​</a></h2><p>Select at least two papers with useful abstracts, or create a review through <strong>Reviews</strong>. Follow the <a href="./reviews">outline and writing guide</a>.</p>',25)])])}const g=t(o,[["render",s]]);export{u as __pageData,g as default};
